def total_minutes(values):
    total = 0
    for value in values:
        if type(value) is not int or value < 0:
            raise ValueError('Expected non-negative integers')
        total += value
    return total

type Item = { title: string; done: boolean };
function summarize(items: Item[]) {
  const completed = items.filter(item => item.done).length;
  return { total: items.length, completed, pending: items.length - completed };
}
