def validate_batch(rows):
    seen = set()
    result = []
    for row in rows:
        key = row.get('id')
        minutes = row.get('minutes')
        if not isinstance(key, str) or not key.strip() or key in seen:
            raise ValueError('Invalid or duplicate id')
        if type(minutes) is not int or minutes < 0:
            raise ValueError('Invalid minutes')
        seen.add(key)
        result.append((key, minutes))
    return result

type PendingJob = { id: string; status: 'pending' };
type SentJob = { id: string; status: 'sent'; remoteId: string };
function markSent(job: PendingJob | SentJob, remoteId: string): SentJob {
  if (job.status === 'sent' && job.remoteId !== remoteId) throw new Error('Conflict');
  return { ...job, status: 'sent', remoteId };
}
